#!/usr/bin/env python3
"""Generate CITATION_VERIFICATION.md: each cited key, its identifier, evidence-matrix access level (research/literature/EVIDENCE_MATRIX.csv)
and the Crossref/arXiv spot-check status recorded in research/literature/NOVELTY_REASSESSMENT_PHASE2.md section 6. Nothing is fixed by guessing."""
import csv, re, pathlib, difflib
P = pathlib.Path(__file__).resolve().parent.parent; R = P.parent.parent
rows = list(csv.DictReader(open(R / "research/literature/EVIDENCE_MATRIX.csv")))
bib = {m.group(1): m.group(0) for m in re.finditer(r"@\w+\{([^,\s]+),.*?\n\}\n", (P / "references.bib").read_text(), re.S)}
nov = (R / "research/literature/NOVELTY_REASSESSMENT_PHASE2.md").read_text()
checked = {k: "spot-checked OK (Crossref/arXiv metadata: title, first authors, venue, year)" for k in re.findall(r"^\| ([A-Za-z0-9]+)(?: \(| \|)", nov.split("## 6.")[1].split("15 entries")[0], re.M)}
special = {"malik2026diffkemp": "FLAG: Crossref (10.1145/3801958) gives the SAME title as malik2021 (authors Malik, Vojnar, Necas; TOSEM 2026-03-16). The matrix calls it the journal extension; not confirmed beyond Crossref metadata. Cited only as 'a journal extension exists'; do not rely on it for content.",
           "liu2025evaluating": "FLAG (key/year): key says 2025, year field 2026 (PACMSE); the tool name 'Cleverest' is not in the bib title.",
           "pradel2025testora": "FLAG (key/year): key says 2025, year field 2026 (ICSE 2026; arXiv 2503.18597).",
           "etemadi2024mokav": "FLAG (key/year): key says 2024, year field 2025 (JSS; arXiv 2406.10375); Crossref lists four authors, arXiv three."}
def ident(e):
    d = re.search(r"doi\s*=\s*\{([^}]*)\}", e); a = re.search(r"(?:eprint|arxiv)\s*=\s*\{([^}]*)\}", e); u = re.search(r"url\s*=\s*\{([^}]*)\}", e)
    return (d.group(1) if d else (a.group(1) if a else (u.group(1) if u else "")))
def match(k, e):
    i = ident(e).lower()
    for r in rows:
        if i and (r["key"].lower() == i or i in r["doi_or_url"].lower()): return r
    t = re.search(r"title\s*=\s*\{(.*?)\},?\n", e, re.S); t = re.sub(r"[{}]", "", t.group(1)).lower() if t else ""
    best = max(rows, key=lambda r: difflib.SequenceMatcher(None, t, r["title"].lower()).ratio())
    return best if difflib.SequenceMatcher(None, t, best["title"].lower()).ratio() > 0.9 else None
nv = [r for r in rows if "NOT VERIFIED" in r["key"]]
out = ["# Citation verification (generated by scripts/build_citation_verification.py)", "",
       "Scope: only keys cited in the manuscript (38). Each `references.bib` entry is copied from `research/literature/VERIFIED_REFERENCES.bib` (never invented; `scripts/build_bib.py` asserts this). `scripts/check_manuscript.py` confirms every `\\cite` key resolves.", "",
       "## Access limits (from the evidence matrix and NOVELTY_REASSESSMENT_PHASE2.md sections 6-7)",
       "- Matrix: 185 rows; FULL TEXT 20 (8 own read, 12 tool-mediated), ABSTRACT 89, METADATA 76, so 109 of 185 (59%) are abstract or metadata only. Tool-mediated reads covered roughly the first 100,000 characters; silence in them is weak evidence of absence.",
       "- ACM Digital Library returned HTTP 403 for every ACM DOI attempted (including re-observation on 2026-11-18); ACM metadata was verified via Crossref only. Shadow TOSEM 2018 is abstract-only; Evans and Savoia was read from an Internet Archive copy of the authors' PDF.",
       "- Not read at all (metadata or abstract only) include Shadow TOSEM full text, Jin et al. 2010, DiffGen, Godefroid REST differential regression, DiffKemp TOSEM 2026, verification-witness papers, abstention and flakiness papers. Prior art for the novelty items may exist that the reviewer could not rule out.",
       "- Single reviewer, known-item and gap-driven search (not systematic), no second screener; 2026 preprints may change; arXiv ids 2607.* and 2610.* were verified only through the live arXiv API on the stated date. No third-party tool was run and no published number reproduced; the manuscript makes no comparison with any of them.", "",
       "## Bibliography discrepancies listed in NOVELTY_REASSESSMENT_PHASE2.md section 6 (flagged, NOT fixed)",
       "1. `malik2026diffkemp`: confirmed from Crossref metadata (10.1145/3801958, Malik, Vojnar, Necas, TOSEM 2026) that the title equals the ICST 2021 paper `malik2021`; whether it is the journal extension or a mis-assigned DOI is unconfirmed beyond Crossref. Flagged; manuscript cites it with a hedge.",
       "2. ArXiv-first year in key versus publication year in the year field: `pradel2025testora` (2026), `liu2025evaluating` (2026), `etemadi2024mokav` (2025). Key naming only; no mismatch in title, authors or venue was found. Keys left unchanged (renaming would diverge from VERIFIED_REFERENCES.bib).",
       f"3. {len(nv)} evidence-matrix rows have `NOT VERIFIED` in `key` (DOI not recorded): " + "; ".join(f"{r['title'][:55]}" for r in nv) + ". None of these is a cited key unless listed below as NOT VERIFIED.",
       "4. `leCong2026patchguru`: arXiv API title was truncated in the first printed line; treated as OK pending a full-title check (novelty file).", "",
       "## Cited keys", "", "| Key | Identifier | Matrix access level | Spot-check status | Note |", "|---|---|---|---|---|"]
notv = 0
for k in sorted(bib):
    r = match(k, bib[k]); acc = r["access_level"] if r else "not matched"
    nvf = r is not None and "NOT VERIFIED" in r["key"]; notv += nvf
    st = "NOT VERIFIED (matrix)" if nvf else checked.get(k, "not spot-checked (identifier from VERIFIED_REFERENCES.bib)")
    out.append(f"| {k} | {ident(bib[k]) or '-'} | {acc} | {st} | {special.get(k, '')} |")
out += ["", f"Cited keys whose matrix row is `NOT VERIFIED`: {notv}. Of the 38 cited keys, {sum(1 for k in bib if k in checked)} were in the 15-entry spot-check of NOVELTY_REASSESSMENT_PHASE2.md section 6; the remainder rely on the VERIFIED_REFERENCES.bib process (Crossref DOI lookup recorded in each entry's note) and were not re-checked here."]
(P / "CITATION_VERIFICATION.md").write_text("\n".join(out) + "\n")
print("written; NOT VERIFIED cited:", notv)
